import numpy as np, sys
def load(path):
    with open(path) as f: lines = f.read().splitlines()
    n = int(lines[0]); atoms = []
    for ln in lines[2:2+n]:
        p = ln.split(); atoms.append((p[0], np.array([float(p[1]),float(p[2]),float(p[3])])))
    return atoms
atoms = load(sys.argv[1])
XYZ = np.array([x for _, x in atoms])
def d(i,j): return np.linalg.norm(XYZ[i]-XYZ[j])
print("Cu-Cu:", [f"{d(i,j):.3f}" for i,j in [(0,1),(2,3),(1,3),(0,2)]])
edges = [(4,5),(32,33),(60,61),(88,89)]
print("alkyne C-C:", [f"{d(i,j):.3f}" for i,j in edges])
cupairs = [(0,1),(2,3),(1,3),(0,2)]
for k,(cu1,cu2) in enumerate(cupairs):
    c1,c2 = edges[k]
    print(f"edge{k}: Cu-C {d(cu1,c1):.2f} {d(cu1,c2):.2f} {d(cu2,c1):.2f} {d(cu2,c2):.2f}")
# bonded pairs to exclude: build bond list by distance < 1.35*sum cov rad
cov = {'H':0.32,'C':0.77,'Si':1.11,'Cu':1.32}
bonds = set()
for i in range(len(atoms)):
    for j in range(i+1, len(atoms)):
        if d(i,j) < 1.3*(cov[atoms[i][0]]+cov[atoms[j][0]]): bonds.add((i,j))
mind, pair, el = 99, None, None
for i in range(len(atoms)):
    for j in range(i+1, len(atoms)):
        if (i,j) in bonds: continue
        dij = d(i,j)
        if dij < mind: mind, pair, el = dij, (i,j), (atoms[i][0],atoms[j][0])
print("shortest non-bonded contact:", round(mind,3), pair, el)
# Si-Cu distances
sis=[6,19,34,47,62,75,90,103]
print("Si-Cu min:", round(min(d(s,c) for s in sis for c in range(4)),3))
